// HasUser applies the HasEdge predicate on the "user" edge.
func HasUser() predicate.Mixtape {
	return predicate.Mixtape(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UserTable, UserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUserWith applies the HasEdge predicate on the "user" edge with a given conditions (other predicates).
func HasUserWith(preds ...predicate.User) predicate.Mixtape {
	return predicate.Mixtape(func(s *sql.Selector) {
		step := newUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasDj applies the HasEdge predicate on the "dj" edge.
func HasDj() predicate.Mixtape {
	return predicate.Mixtape(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DjTable, DjColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDjWith applies the HasEdge predicate on the "dj" edge with a given conditions (other predicates).
func HasDjWith(preds ...predicate.DJ) predicate.Mixtape {
	return predicate.Mixtape(func(s *sql.Selector) {
		step := newDjStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Mixtape) predicate.Mixtape {
	return predicate.Mixtape(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Mixtape) predicate.Mixtape {
	return predicate.Mixtape(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Mixtape) predicate.Mixtape {
	return predicate.Mixtape(sql.NotPredicates(p))
}
